import { code } from '../../code.ts';
import { androidNamespace } from '../names.ts';
import { ndkVersion } from '../versions.ts';
import type { Plugin } from '../values.ts';

// The path of the file in plugins/android.
export const path = ({ id }: Plugin) => `${id}/build.gradle.kts`;

export default ({ id }: Plugin) => code`
// Generated by plugins/tools/generate.ts from plugins/plugins/${id}/plugin.json; do not edit.
plugins {
    id("com.android.library")
}

android {
    namespace = "${androidNamespace(id)}"
    compileSdk = 35
    ndkVersion = "${ndkVersion()}"

    defaultConfig {
        minSdk = 23
        consumerProguardFiles("consumer-rules.pro")
        val abis = providers.gradleProperty("maplibre.abis").orElse("all").get()
        ndk {
            abiFilters += if (abis == "all") {
                listOf("armeabi-v7a", "arm64-v8a", "x86", "x86_64")
            } else {
                abis.split(" ")
            }
        }
        externalNativeBuild.cmake.arguments += "-DANDROID_STL=c++_static"
    }

    flavorDimensions += "renderer"
    productFlavors {
        listOf("opengl", "vulkan", "multiBackend").forEach { renderer ->
            // Select the SDK flavor that exports the plugin API.
            create("\${renderer}WithPluginApi") {
                dimension = "renderer"
                buildConfigField("boolean", "MULTI_BACKEND", (renderer == "multiBackend").toString())
            }
        }
    }

    buildFeatures {
        prefab = true
        buildConfig = true
    }
    externalNativeBuild {
        cmake {
            path = file("src/main/cpp/CMakeLists.txt")
            version = "3.24.0+"
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin {
    jvmToolchain(17)
}

dependencies {
    implementation("org.maplibre.gl:android-sdk:0.0.0-local")
}
`;
